import json,hashlib
p='/workspace/scratch/volume4/batch359-368.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(362,[
('قوله: «الدرجة الثالثة: أن لا يناسم رسمك سبقه».', 'Его слова: «Третья степень — чтобы твой сотворённый облик не соприкасался с Его предшествованием».'),
('الرسم هو الشخص عندهم، وهو محدث مخلوق، والرب تعالى هو القديم الخالق، فإذا تحقق العبد بالحقيقة شهد الحق وحده متفردا عن خلقه، فلم يناسم رسمه سبق الحق وأوليته. والمناسمة كالمشامة، يقال: ناسمه، أي شامه، فاستعار الشيخ اللفظة لأدنى المقاربة والملابسة، أي لا يداني رسمك سبقه، ولو بأدنى مناسمة، بل تشهد الحق وحده منفردا عن كل ما سواه.', '«Расм» в их словоупотреблении — сама личность; она возникшая и сотворённая, тогда как Всевышний Господь — Предвечный Творец. Когда раб утверждается в реальности, он созерцает одного Истинного, обособленного от Его творений, и его сотворённый облик не соприкасается с предшествованием и первенством Истинного. «Мунасама» подобна «мушамма» — взаимному обонянию: говорят «насамаху», то есть «вдохнул его запах». Шейх заимствовал это выражение для самого малого сближения и соприкосновения. То есть твой сотворённый облик не должен приближаться к Его предшествованию даже самым малым соприкосновением: ты созерцаешь одного Истинного, обособленного от всего остального.'),
('وهم يشيرون بذلك إلى أمر، وهو أن الله سبحانه كان ولا شيء معه، وهو الآن على ما عليه كان.', 'Этим они указывают на следующее: Пречистый Аллах был, и ничего не было вместе с Ним; и сейчас Он таков, каким был.'),
('فأما اللفظ الأول وهو «كان الله ولا شيء معه» فهذا قد روي في «الصحيح» في بعض ألفاظ حديث عمران بن حصين، وإن كان اللفظ الثابت: «كان الله ولم يكن شيء قبله»، وهو المطابق لقوله في الحديث الآخر الصحيح: «أنت الأول فليس قبلك شيء»، ولم يقل: فليس معك شيء.', 'Первая формулировка — «Был Аллах, и ничего не было вместе с Ним» — передана в «Сахихе» в некоторых версиях хадиса ‘Имрана ибн Хусайна. Однако установленная формулировка такова: «Был Аллах, и ничего не было до Него». Она соответствует Его описанию в другом достоверном хадисе: «Ты — Первый, и до Тебя ничего нет». Не сказано: «И с Тобой ничего нет».'),
('وأما قوله: «وهو الآن على ما عليه كان» فزيادة في الحديث ليست منه، بل زادها بعض المتحذلقين، وهي باطلة قطعا، فإن الله مع خلقه بالعلم', 'Что касается слов «и сейчас Он таков, каким был», это добавление к хадису, которое к нему не относится: его добавили некоторые умствующие люди. Оно безусловно ложно, ведь Аллах — со Своими творениями знанием')])
page(363,[
('والتدبير والقدرة، ومع أوليائه بالحفظ والكلاءة والنصرة، وهم معه بالموافقة والمحبة، وصارت هذه اللفظة مجنا وترسا للملاحدة من الاتحادية، فقالوا: إنه لا وجود سوى وجوده أزلا وأبدا وحالا، فليس في الوجود إلا الله وحده، وكل ما تراه وتلمسه وتذوقه وتشمه وتباشره فهو حقيقة الله.', 'управлением и могуществом, а со Своими приближёнными — охраной, попечением и поддержкой; они же с Ним — следованием Его воле и любовью. Это выражение стало щитом и заслоном для безбожников из числа приверженцев единения. Они сказали, что нет иного бытия, кроме Его бытия, — ни предвечно, ни вечно, ни сейчас: в бытии есть лишь один Аллах, а всё, что ты видишь, осязаешь, вкушаешь, обоняешь и с чем соприкасаешься, есть реальность Аллаха.'),
('وأما أهل التوحيد فقد يطلقون هذه اللفظة ويريدون بها معنى صحيحا، وهو أن الله سبحانه لم يزل متفردا بنفسه عن خلقه، ليس مخالطا لهم، ولا حالا فيهم، ولا ممازجا لهم، بل هو بائن عنهم بذاته وصفاته.', 'Люди единобожия иногда употребляют это выражение, подразумевая верный смысл: Пречистый Аллах всегда обособлен Сам по Себе от Своих творений, не смешивается с ними, не пребывает в них и не сливается с ними; Он отделён от них Своей Сущностью и качествами.'),
('وأما الشيخ وأرباب الفناء فقد يعنون معنى أخص من ذلك، وهو المشار إليه بقوله: «أن لا يناسم رسمك سبقه»، أي لا ترى أنك معه بل تراه وحده، ولهذا قال: «فتسقط الشهادات، وتبطل العبارات، وتفنى الإشارات»، يعني: أنك إذا لم تشهد معه غيره، وأسقطت الغير من الشهود لا من الوجود، بخلاف ما يقول الملحد الاتحادي: إنك تسقط الغير شهودا ووجودا = سقطت الشهادات والعبارات والإشارات؛ لأنها صفات العبد المحدث المخلوق، والفناء يوجب إسقاطها.', 'Шейх же и люди фана могут иметь в виду более особый смысл, на который указывают его слова «чтобы твой сотворённый облик не соприкасался с Его предшествованием». То есть ты не видишь себя вместе с Ним, а видишь Его одного. Поэтому он сказал: «Тогда отпадают свидетельства, утрачивают силу выражения и исчезают указания». Смысл в том, что, когда ты не созерцаешь вместе с Ним иного и устраняешь иное из созерцания, а не из бытия, отпадают свидетельства, выражения и указания, поскольку они — качества возникшего и сотворённого раба, а фана требует их устранения. Это отличается от слов безбожника, приверженца единения, по которому ты устраняешь иное и из созерцания, и из бытия.'),
('والمعنى: أن الواصل إلى هذا المقام لا يرى مع الحق سواه، فيمحو السوى في شهوده. وعند الملحد يمحوه من الوجود. والله الموفق.', 'Итак, достигший этой стоянки не видит наряду с Истинным ничего другого и стирает иное в своём созерцании. Безбожник же стирает его из бытия. Аллах дарует успех.')])
page(364,[
('فصل', 'Раздел'),
('قال: «باب التلبيس. قال الله تعالى: {وللبسنا عليهم ما يلبسون} [الأنعام: ٩]».', 'Он сказал: «Глава о тальбисе — введении в заблуждение. Всевышний Аллах сказал: {وللبسنا عليهم ما يلبسون} — “И Мы запутали бы для них то, что они сами путают” [6:9]».'),
('ليته رحمه الله لم يستشهد بهذه الآية في هذا الباب، فإن الاستشهاد بها على مقصوده أبعد شاهد عليه، وأبطله شهادة. وليته لم يسم هذا الباب بالتلبيس، واختار له اسما أحسن منه موقعا.', 'Лучше бы он, да помилует его Аллах, не приводил этот аят как свидетельство в данной главе: применительно к его цели это самое далёкое и самое несостоятельное свидетельство. Лучше бы он не называл эту главу тальбисом, а выбрал более подходящее имя.'),
('فأما الآية: فإن معناها غير ما عقد له الباب من كل وجه، فإن المشركين قالوا تعنتا في كفرهم: {لولا أنزل عليه ملك} [الأنعام: ٨]، يعنون: ملكا نشاهده ونراه، نشهد له ونصدقه، وإلا فالملك كان ينزل عليه بالوحي من الله. فأجاب الله تعالى عن هذا، وبين الحكمة في عدم إنزال الملك على الوجه الذي اقترحوه بأنه لو أنزل ملكا كما اقترحوا، ولم يؤمنوا به ويصدقوه = لعوجلوا بالعذاب، كما استمرت به سنته تعالى مع الكفار في آيات الاقتراح إذا جاءتهم ولم يؤمنوا، فقال: {ولو أنزلنا ملكا لقضي الأمر ثم لا ينظرون} [الأنعام: ٨]. ثم بين سبحانه أنه لو أنزل ملكا كما اقترحوا لما حصل به مقصودهم؛ لأنه إن أنزله في صورته لم يقدروا على التلقي عنه، إذ البشر لا يقدر على مخاطبة الملك ومباشرته. وقد كان رسول الله صلى الله عليه وسلم ـ وهو أقوى الخلق ـ إذا نزل عليه الملك كرب لذلك، وأخذته البرحاء، وتحدر منه العرق في اليوم الشاتي. وإن', 'Смысл аята совершенно отличен от того, чему он посвятил главу. Многобожники, упорствуя в своём неверии, сказали: {لولا أنزل عليه ملك} — «Почему к нему не ниспослан ангел?» [6:8]. Они имели в виду: ангел, которого мы наблюдаем и видим, чьё свидетельство признаём и которому верим. Ведь в противном случае ангел и так нисходил к нему с откровением от Аллаха. Всевышний Аллах ответил на это и разъяснил мудрость того, что ангел не был ниспослан в предложенном ими виде: если бы ангел был ниспослан, как они предложили, а они не уверовали в него и не признали его, то их незамедлительно постигло бы наказание. Так постоянно проявлялся установленный Всевышним порядок в отношении неверующих, когда к ним приходили затребованные ими знамения, а они не веровали. Он сказал: {ولو أنزلنا ملكا لقضي الأمر ثم لا ينظرون} — «Если бы Мы ниспослали ангела, дело было бы уже решено, и им не дали бы отсрочки» [6:8]. Затем Пречистый разъяснил, что, даже если бы Он ниспослал ангела по их предложению, их цель не была бы достигнута. Если бы Он ниспослал его в собственном облике, они не смогли бы воспринимать от него, поскольку человек не способен разговаривать с ангелом и непосредственно соприкасаться с ним. Даже Посланник Аллаха, да благословит его Аллах и приветствует, самый сильный из творений, испытывал тяжесть при нисхождении к нему ангела: его охватывал мучительный жар, и с него стекал пот в холодный день. Если же')])
page(365,[
('جعله في صورة رجل حصل لهم لبس: هل هو ملك أم رجل؟ فقال: {ولو جعلناه ملكا لجعلناه رجلا} أي في صورة رجل {وللبسنا عليهم} في هذه الحال {ما يلبسون} [الأنعام: ٩]، فإنهم حينئذ على أنفسهم يلبسون إذا رأوا الملك في صورة الإنسان: هذا إنسان، وليس بملك. فهذا معنى الآية، فأين تجده مما عقد له الباب؟', 'Он придаст ему облик мужчины, у них возникнет неясность: ангел это или человек? Поэтому Он сказал: {ولو جعلناه ملكا لجعلناه رجلا} — «Если бы Мы сделали его ангелом, то сделали бы его мужчиной», то есть в облике мужчины, {وللبسنا عليهم} — «и Мы запутали бы для них» в таком случае {ما يلبسون} — «то, что они сами путают» [6:9]. Ведь тогда они сами запутают себя, увидев ангела в человеческом облике: «Это человек, а не ангел». Таков смысл аята. Где же ты найдёшь в нём то, чему посвящена глава?'),
('فصل', 'Раздел'),
('قال: «التلبيس: تورية بشاهد معار عن موجود قائم».', 'Он сказал: «Тальбис — двусмысленное указание посредством заимствованного свидетельства, скрывающее налично существующее».'),
('لما كانت التورية إظهار خلاف المراد، بأن يذكر شيئا يوهم أنه مراده، وليس هو بمراده، بل ورى بالمذكور عن المراد = فسر التلبيس بها، وفي الحديث: «كان رسول الله صلى الله عليه وسلم إذا أراد غزوة ورى بغيرها». مثاله: أن يريد غزو خيبر فيقول للناس: كيف بطريق نجد وما بها من المياه؟ ونحو ذلك.', 'Поскольку двусмысленное указание состоит в обнаружении того, что отличается от подразумеваемого, — человек упоминает нечто, создающее впечатление, что имеет в виду именно это, хотя он имеет в виду другое и упомянутым скрывает подразумеваемое, — он и объяснил тальбис через него. В хадисе сказано: «Когда Посланник Аллаха, да благословит его Аллах и приветствует, намеревался совершить военный поход, он скрывал это указанием на другой». Например, он намеревается идти на Хайбар, а спрашивает людей: «Какова дорога в Неджд и как там с водой?» — и тому подобное.'),
('فهاهنا شيئان: أمر ستره الموري الملبس، وأمر ستر به ما ورى عنه، فأشار المصنف إلى الأمرين بقوله: «تورية بشاهد معار عن موجود قائم». فأما التورية فقد عرفتها، وأما الشاهد فهو الذي توري به عن مرادك وتستشهد به، والشاهد المعار هو الذي استعير لغيره ليشهد له، فهو شاهد استعير لمشهود قائم. فالتورية: أن تذكر ما يحتمل معنيين، ومقصودك خلاف الذي', 'Здесь две вещи: то, что скрыл прибегающий к двусмысленности и тальбису, и то, чем он прикрыл скрываемое. На обе автор указал словами «двусмысленное указание посредством заимствованного свидетельства, скрывающее налично существующее». Что такое двусмысленное указание, ты уже узнал. Свидетельство — то, чем ты скрываешь свой замысел и на что ссылаешься в подтверждение. Заимствованное свидетельство — то, что заимствовано для другого, чтобы свидетельствовать о нём: оно заимствовано для налично существующего предмета свидетельства. Таким образом, двусмысленное указание — это упоминание того, что допускает два смысла, причём ты подразумеваешь не тот смысл, который')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
